<?php $pageTitle='Tutorials';require_once __DIR__.'/functions.php';$items=db()->query("SELECT * FROM tutorials ORDER BY id DESC")->fetchAll();include 'includes/header.php';?><section class="page-head"><div class="container"><h1>Tutorials</h1><p class="muted">Free, focused lessons. Add new tutorials from Admin.</p></div></section><section class="section" style="padding-top:10px"><div class="container cards"><?php foreach($items as $x):?><article class="card"><div class="thumb"><?=e($x['icon'])?></div><div class="card-body"><h3><?=e($x['title'])?></h3><p><?=e($x['description'])?></p><?php if($x['url']&&$x['url']!=='#'):?><a class="primary" href="<?=e($x['url'])?>" target="_blank" rel="noopener">Start Learning</a><?php else:?><span class="secondary">Coming soon</span><?php endif;?></div></article><?php endforeach;?></div></section><?php include 'includes/footer.php';?>
